def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1))
    if len(labs) > 1:
        st = np.array(feats.stratum)
        S = np.column_stack([np.ones(n)] + [(st == l).astype(float) for l in labs[1:]])

    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    def pval(base, extra):
        d = 2 * (ll(np.column_stack([base, extra])) - ll(base))
        return float(stats.chi2.sf(max(d, 0.0), 1))

    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    alpha = 0.15 / p
    sel = []
    while len(sel) < MAX_DRIVERS:
        base = np.column_stack([S] + [X[:, j] for j in sel])
        best, bp = None, 1.0
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            pv = pval(base, X[:, j])
            if pv < bp: best, bp = j, pv
        if best is None or bp > (alpha if not sel else 0.002): break
        sel.append(best)
    changed = True
    while changed and len(sel) > 1:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            base = np.column_stack([S] + [X[:, k] for k in rest])
            if pval(base, X[:, j]) > 0.002:
                sel.remove(j); changed = True; break
    prods = []
    base = np.column_stack([S] + [X[:, k] for k in sel])
    marg = [pval(S, X[:, j]) for j in range(p)]
    top = [int(j) for j in np.argsort(marg)[:12]]
    pairs = {tuple(sorted((a, b))) for a in top for b in top if a != b}
    pairs |= {tuple(sorted((a, b))) for a in sel for b in range(p) if a != b}
    npairs = len(pairs)
    best, bp = None, 1.0
    for a, b in sorted(pairs):
        Z = np.column_stack([base] + [X[:, k] for k in (a, b) if k not in sel])
        pv = pval(Z, X[:, a] * X[:, b])
        if pv < bp: best, bp = (a, b), pv
    if best is not None and bp < 0.05 / max(npairs, 1):
        prods.append(best)
        for k in best:
            if k not in sel and len(sel) < MAX_DRIVERS: sel.append(k)
    drivers = tuple(ids[j] for j in sel)
    return Design(drivers=drivers, columns=drivers,
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

